import{_ as o,l as n,o as e,c as l,v as i,p,x as t,d as s,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"二价与维克里","description":"","frontmatter":{"title":"二价与维克里","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/second-price-vickrey.md","filePath":"econ/second-price-vickrey.md","lastUpdated":1789023840000}'),d={name:"econ/second-price-vickrey.md"};function _(B,a,h,A,u,m){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=i('<h1 id="二价与维克里" tabindex="-1">二价与维克里 <a class="header-anchor" href="#二价与维克里" aria-label="Permalink to &quot;二价与维克里&quot;">​</a></h1><div class="epigraph"><p>第二价格密封拍卖中，报出真实估值是占优策略：报价只决定是否得到物品，应付价格由别人的最高报价钉住。</p><footer>—— Vickrey, Counterspeculation, Auctions, and Competitive Sealed Tenders, Journal of Finance, 1961</footer></div><p><a href="/econ/english-dutch-auction">上一课</a>（英式与荷式拍卖）。的一价均衡要算遮挡，函数依赖 \\(F\\) 与 \\(n\\)。缺口是：有没有规则让说真话成为占优，从而不必知道先验？Vickrey 的第二价格密封：最高报价得物，支付<strong>第二高</strong>报价。本课钉占优策略真话，不把收入等价提前写成定理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IPV 仍在：\\(v_i\\) 私有。每人报 \\(b_i\\)。令 \\(p_{(2)}\\) 为别人报价中的最高。若 \\(b_i\\gt p_{(2)}\\) 则得物并付 \\(p_{(2)}\\)，否则得零。比较报 \\(b_i=v_i\\) 与报别的数：</p><ul><li>报高过 \\(v_i\\)：只在 \\(v_i\\lt p_{(2)}\\lt b_i\\) 时改变结果，此时赢了但 \\(p_{(2)}\\gt v_i\\)，净支付为负；其余情形与报真值相同。</li><li>报低于 \\(v_i\\)：只在 \\(b_i\\lt p_{(2)}\\lt v_i\\) 时改变结果，此时本该赢的互利交易被自己丢掉。</li></ul><p>故报真值对每一 \\(p_{(2)}\\) 都不差，且对某些严格更好——占优策略，不只是某个先验下的 BNE。英式口头拍卖在 IPV 下与二价策略等价：一直留到价格碰到自己的 \\(v\\)。</p><h3 id="真话不是道德-是支付与分配解耦" tabindex="-1">真话不是道德，是支付与分配解耦 <a class="header-anchor" href="#真话不是道德-是支付与分配解耦" aria-label="Permalink to &quot;真话不是道德，是支付与分配解耦&quot;">​</a></h3><p>一价里同一数字既当「我要不要赢」又当「赢了付多少」，所以要遮挡。二价把支付钉在别人的报上，自己的报只当门槛。占优来自这条会计，不是来自「维克里拍卖更公平」。共同价值下真话不必占优：别人的报带着关于物品的信息，\\(p_{(2)}\\) 不再是与你无关的数。</p><p><span class="marginnote">两人时，二价占优均衡的结果是：高估值者得物，付低估值者的报。若两人都说真话，成交价是第二高估值。一价均衡遮挡后，谁赢、期望付款，对称 IPV 下可以与这一结果对上——那是后课等价，本课只钉占优。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：IPV、单一物品、第二价格规则（密封或英式）。结论：说真话是（弱）占优；均衡配置有效（最高估值者得物），不必解微分方程。风险厌恶不破坏占优真话——因为论证不对概率取期望。预算约束、保留价改参与，不改「已参与则报 \\(v\\)」。</p><p>多物品、公共物品的维克里–克拉克–格罗夫斯（VCG）把同一思想写成：付你给别人造成的外部性。本课单物品二价是 VCG 的特例，不展开一般机制。</p>',13)),(e(),p(c,null,{default:t(()=>[E(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20FP%5B%22%E4%B8%80%E4%BB%B7%EF%BC%9Ab%20%E6%97%A2%E5%88%86%E9%85%8D%E5%8F%88%E8%AE%A1%E4%BB%B7%22%5D%20--%3E%20SHADE%5B%22BNE%20%E9%81%AE%E6%8C%A1%EF%BC%8C%E4%BE%9D%E8%B5%96%20F%22%5D%0A%20%20SP%5B%22%E4%BA%8C%E4%BB%B7%EF%BC%9Ab%20%E5%8F%AA%E5%BD%93%E9%97%A8%E6%A7%9B%EF%BC%8C%E4%BB%98%E7%AC%AC%E4%BA%8C%E9%AB%98%22%5D%20--%3E%20DOM%5B%22%E5%8D%A0%E4%BC%98%E7%AD%96%E7%95%A5%E6%8A%A5%20v%22%5D%0A%20%20DOM%20--%3E%20EFF%5B%22%E6%9C%80%E9%AB%98%E4%BC%B0%E5%80%BC%E8%80%85%E5%BE%97%E7%89%A9%22%5D%0A%20%20DOM%20--%3E%20RE%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%9C%9F%E6%9C%9B%E6%94%B6%E5%85%A5%E5%8F%AF%E4%BB%A5%E5%AF%B9%E9%BD%90%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>占优论证逐点打在 \\(p_{(2)}\\) 上，因此不需要共同先验，甚至不需要知道有几个对手——只要 IPV、单物品、付第二高。这与<a href="/econ/revelation-principle">显示原理</a>的占优策略版衔接：二价已经是直接机制，真话 IC 成立。一价不是：直接报 \\(v\\) 在一价里不是均衡，必须先遮挡再报。</p><p>无效率从哪来？若价值有外部效应（拍卖品污染邻居），真话仍关于自己的 \\(v\\)，社会有效另要加项。若可合谋，两人可以压低第二价：占优是针对单人偏离，挡不住联盟。假名投标（一人扮两人）也能操纵第二价。占优不是联盟稳定。</p><h3 id="与林达尔、庇古不是同一句话" tabindex="-1">与林达尔、庇古不是同一句话 <a class="header-anchor" href="#与林达尔、庇古不是同一句话" aria-label="Permalink to &quot;与林达尔、庇古不是同一句话&quot;">​</a></h3><p>公共品里「报 MRS」不是占优，林达尔要真实偏好却给谎报激励。维克里能真话，是因为支付按你给别人造成的边际伤害（把第二高挤掉）来收，把外部性内部化进自己的问题——单物品拍卖的「外部性」恰好是占走了物品。公共品多人受益，VCG 能真话但会破预算；那是后课机制，本课不把二价写成公共品融资。</p><p><span class="marginnote">荷兰式（降价）策略等价于一价；英式等价于二价。四种经典拍卖在 IPV 对称风险中性下期望收入相同，是收入等价的内容。本课只需要：二价占优真话，一价否。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>关联价值、赢家诅咒下，英式与二价密封不再策略等价：英式能看见别人退出，信息不同。风险厌恶改一价遮挡，不改二价真话。保留价提高效率可能下降（把物品留给卖方），但真话仍是占优。</p><p>弱占优：在 \\(p_{(2)}=v_i\\) 的零测集上，报高报低都无差（反正支付为零）。严格来说真话是弱占优。这不影响「不必知道 \\(F\\)」：没有任何先验会让人严格想偏离真话。</p><p>拍卖课序下一步是收入等价：同一 \\(G(v)\\) 的机制期望支付相同。本课默认：IPV 二价（维克里）中报真值是占优策略；有效性来自最高估值者得物，不来自卖方收入最大。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>二价把「是否赢」与「赢了付多少」拆开，真话占优。</li><li>论证不依赖 \\(F\\) 与 \\(n\\)，只依赖 IPV。</li><li>一价必须遮挡；二价不必。</li><li>占优挡单人偏离，挡不住合谋与假名。</li><li>出处：Vickrey, <em>Journal of Finance</em>, 1961。</li></ul>',12))])}const v=o(d,[["render",_]]);export{f as __pageData,v as default};
